term = 20   # which term (0 is the 1st term)

def fib_plain(k, calls):
    calls[0] += 1                                    # count every call
    if k < 2:
        return k
    return fib_plain(k - 1, calls) + fib_plain(k - 2, calls)

def fib_dp(count):
    fib = [0, 1]
    for i in range(2, count):
        fib.append(fib[i - 1] + fib[i - 2])          # use stored values
    return fib[count - 1], max(count - 2, 0)

if term < 1:
    print("term must be 1 or more")
else:
    value, additions = fib_dp(term)
    print("Term", term, "=", value)
    print("With DP: additions =", additions)
    if term <= 25:
        calls = [0]
        fib_plain(term - 1, calls)
        print("Without DP: function calls =", calls[0])
    else:
        print("Without DP it would be too slow; keep term 25 or less to compare.")
